    ---------------------------------------------------------------------------

    -- Señales para calcular la dirección de memoria
    signal block_x, block_y : integer range 0 to 255;
    signal rom_address      : integer range 0 to (ROM_WIDTH * ROM_HEIGHT) - 1;
    signal color_data       : std_logic_vector(11 downto 0);

begin

    -- PROCESO DE LECTURA DE ROM (Sincronizado con el reloj)
    process(clk)
    begin
        if rising_edge(clk) then
            -- 1. Convertir coordenadas de pantalla a coordenadas de bloque (8x8)
            block_x <= pixel_x / 8;
            block_y <= pixel_y / 8;

            -- 2. Comprobación de seguridad (para no leer fuera de la memoria)
            if (block_x < ROM_WIDTH) and (block_y < ROM_HEIGHT) then
                -- 3. Calcular la dirección lineal en la tabla
                -- Dirección = (Fila Actual * Ancho Total) + Columna Actual
                rom_address <= (block_y * ROM_WIDTH) + block_x;
                
                -- 4. Leer el dato de la tabla
                color_data <= IMAGEN_ROM(rom_address);
            else
                -- Si estamos fuera de rango (ej: pixel_y > 1023), negro
                color_data <= X"000";
            end if;
        end if;
    end process;

    -- Desempaquetar el color de 12 bits a las salidas RGB
    red_out   <= color_data(11 downto 8);
    green_out <= color_data(7 downto 4);
    blue_out  <= color_data(3 downto 0);

end Behavioral;